  x isa Vector && return join((str(y) for y in x), ",")
  if x isa Obj
    f = find(x.cls, :toString)
    f.kind === :method && return str(f.value(x, EMPTY))
    f.kind === :getter && return str(f.value(x, EMPTY))
    return x.cls.name
  end
  x isa Cls && return x.name
  x isa Many && return join((str(y) for y in x.items), ",")
  x isa AbstractString && return String(x)
  string(x)
end

