function contains_(@nospecialize(xs), @nospecialize(x))
  xs isa AbstractString && return occursin(str(x), xs)
  for y in items(xs); eq(y, x) && return true; end
  false
end
function index_of(@nospecialize(xs), @nospecialize(x))
  if xs isa AbstractString
    r = findfirst(str(x), xs)
    r === nothing && return nothing
    return Float64(length(xs, 1, prevind(xs, first(r))))
  end
  l = items(xs)
  for i in eachindex(l); eq(l[i], x) && return Float64(i - 1); end
  nothing
end
function first_(@nospecialize(xs))
  xs isa AbstractString && return isempty(xs) ? nothing : string(first(xs))
  l = items(xs); isempty(l) ? nothing : l[1]
end
function last_(@nospecialize(xs))
  xs isa AbstractString && return isempty(xs) ? nothing : string(last(xs))
  l = items(xs); isempty(l) ? nothing : l[end]
end
join_(@nospecialize(xs), @nospecialize(sep)) = join((str(x) for x in items(xs)), str(sep))
function quoted(@nospecialize(x))
  s = str(x)
  io = IOBuffer()
  print(io, '"')
  for c in s
    if c == '"'; print(io, "\\\"")
    elseif c == '\\'; print(io, "\\\\")
    elseif c == '\n'; print(io, "\\n")
    elseif c == '\r'; print(io, "\\r")
    elseif c == '\t'; print(io, "\\t")
    elseif c < ' '; print(io, "\\u", string(UInt32(c), base = 16, pad = 4))
    else print(io, c)
    end
  end
  print(io, '"')
  String(take!(io))
end
function most(@nospecialize(xs), @nospecialize(key))
  best = nothing; at_ = -1; bk = -Inf; l = items(xs)
  for i in eachindex(l)
    k = num(rinvoke(key, Any[l[i]]))
    if best === nothing || k > bk; best = l[i]; at_ = i - 1; bk = k; end
  end
  best === nothing ? nothing : Any[best, Float64(at_)]
end
function sorted_by(@nospecialize(xs), @nospecialize(key))
  l = items(xs)
  ks = Float64[num(rinvoke(key, Any[x])) for x in l]
  p = sortperm(eachindex(l); by = i -> ks[i], alg = Base.MergeSort)
  Any[l[i] for i in p]
end
summed(@nospecialize(xs)) = (s = 0.0; for x in items(xs); s += num(x); end; s)
rfail(@nospecialize(says)) = error(str(says))
codepoints(s::AbstractString) = Any[Float64(UInt32(c)) for c in s]
from_codepoints(@nospecialize(xs)) = String([Char(Int(num(c))) for c in items(xs)])
blank(@nospecialize(c)) = (d = num(c); d == 32 || d == 9 || d == 10 || d == 13)
function number(@nospecialize(s))
  t = strip(str(s))
  t == "Infinity" && return Inf
  t == "-Infinity" && return -Inf
  v = tryparse(Float64, t)
  v === nothing ? NaN : v
end
function many(@nospecialize(xs))
  Many(items(xs))
end
function collapse(xs::Vector{Any})
  isempty(xs) && return Many(xs)
  f = xs[1]
  for i in xs
    (i === f || (i isa Vector && f isa Vector && eq(i, f))) || return Many(xs)
  end
  f
end
function text_drop(s::AbstractString, n::Int)
  n <= 0 && return String(s)
  i = nextind(s, 0, n + 1)
  i > ncodeunits(s) ? "" : String(s[i:end])
end
text_take(s::AbstractString, n::Int) = n <= 0 ? "" : String(first(s, n))

# --- a member Ray knows on a list, a text or a number - and any object's own member of that name otherwise ---
# (`Expr.split(e, name)` is Expr's own): every one takes what it is given, and hands it all to the object's member
core(@nospecialize(x)) = x isa Vector{Any} || x isa String || x isa Float64 || x === nothing || x isa Many || x isa Bool || x isa Vector || x isa AbstractString || x isa Real
function m_push(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :push, Any[a...])
  push!(xs, a[1]); xs
end
m_chars(@nospecialize(xs), a...) = xs isa AbstractString ? codepoints(xs) : own(xs, :chars, a)
m_pop(@nospecialize(xs), a...) = core(xs) ? (isempty(xs) ? nothing : pop!(xs)) : own(xs, :pop, a)
m_map(@nospecialize(xs), a...) = core(xs) ? Any[rinvoke(a[1], Any[x]) for x in items(xs)] : rcall(xs, :map, Any[a...])
function m_for(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :for, Any[a...])
  f = a[1]
  for x in items(xs); rinvoke(f, Any[x]); end
  nothing
end
function m_some(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :some, Any[a...])
  for x in items(xs); truthy(rinvoke(a[1], Any[x])) && return true; end
  false
end
function m_every(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :every, Any[a...])
  for x in items(xs); truthy(rinvoke(a[1], Any[x])) || return false; end
  true
end
function m_reduce(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :reduce, Any[a...])
  acc = a[1]
  for x in items(xs); acc = rinvoke(a[2], Any[acc, x]); end
  acc
end
m_starts_with(@nospecialize(xs), a...) = core(xs) ? startswith(xs, str(a[1])) : rcall(xs, :starts_with, Any[a...])
m_ends_with(@nospecialize(xs), a...) = core(xs) ? endswith(xs, str(a[1])) : rcall(xs, :ends_with, Any[a...])
function m_replace(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :replace, Any[a...])
  x = str(a[1])
  isempty(x) ? String(xs) : replace(xs, x => str(a[2]))
end
function m_split(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :split, Any[a...])
  sep = str(a[1])
  isempty(sep) && return items(xs)
  Any[String(p) for p in split(xs, sep; keepempty = true)]
end
"""a member of the object's own, where a recognised one is written without arguments (`x.trim`)"""
own(@nospecialize(xs), n::Symbol, a) = isempty(a) ? rget(xs, n) : rcall(xs, n, Any[a...])
m_trim(@nospecialize(xs), a...) = core(xs) ? String(strip(xs)) : own(xs, :trim, a)
m_upper(@nospecialize(xs), a...) = core(xs) ? uppercase(xs) : own(xs, :upper, a)
m_lower(@nospecialize(xs), a...) = core(xs) ? lowercase(xs) : own(xs, :lower, a)
m_lines(@nospecialize(xs), a...) = core(xs) ? m_split(xs, "\n") : own(xs, :lines, a)
m_contains(@nospecialize(xs), a...) = core(xs) ? contains_(xs, a[1]) : rcall(xs, :contains, Any[a...])
m_index_of(@nospecialize(xs), a...) = core(xs) ? index_of(xs, a[1]) : rcall(xs, :index_of, Any[a...])
m_join(@nospecialize(xs), a...) = core(xs) ? join_(xs, a[1]) : rcall(xs, :join, Any[a...])
m_first(@nospecialize(xs), a...) = core(xs) ? first_(xs) : own(xs, :first, a)
m_last(@nospecialize(xs), a...) = core(xs) ? last_(xs) : own(xs, :last, a)
m_empty(@nospecialize(xs), a...) = core(xs) ? num(len(xs)) == 0 : own(xs, :empty, a)
function m_take(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :take, Any[a...])
  n = index_int(a[1])
  xs isa AbstractString && return text_take(xs, n)
  l = items(xs)
  l[1:clamp(n, 0, length(l))]
end
function m_drop(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :drop, Any[a...])
  n = index_int(a[1])
  xs isa AbstractString && return text_drop(xs, n)
  l = items(xs)
  l[clamp(n, 0, length(l))+1:end]
end
m_rest(@nospecialize(xs), a...) = core(xs) ? m_drop(xs, 1.0) : own(xs, :rest, a)
function m_concat(@nospecialize(xs), a...)
  core(xs) || return rcall(xs, :concat, Any[a...])
  xs isa AbstractString && return xs * str(a[1])
  vcat(items(xs), items(a[1]))
end
function m_reverse(@nospecialize(xs), a...)
  core(xs) || return own(xs, :reverse, a)
  xs isa AbstractString && return reverse(xs)
  reverse(items(xs))
end
m_sum(@nospecialize(xs), a...) = core(xs) ? summed(xs) : own(xs, :sum, a)
m_most(@nospecialize(xs), a...) = core(xs) ? most(xs, a[1]) : rcall(xs, :most, Any[a...])
m_sorted_by(@nospecialize(xs), a...) = core(xs) ? sorted_by(xs, a[1]) : rcall(xs, :sorted_by, Any[a...])
m_each(@nospecialize(xs), a...) = core(xs) ? Many(items(xs)) : own(xs, :each, a)
m_sqrt(@nospecialize(x), a...) = arith(x) ? (v = num(x); v < 0 ? NaN : sqrt(v)) : own(x, :sqrt, a)
m_floor(@nospecialize(x), a...) = arith(x) ? floor(num(x)) : own(x, :floor, a)
m_abs(@nospecialize(x), a...) = arith(x) ? abs(num(x)) : own(x, :abs, a)
m_magnitude(@nospecialize(x), a...) = arith(x) ? abs(num(x)) : own(x, :magnitude, a)
m_cos(@nospecialize(x), a...) = arith(x) ? (v = num(x); isfinite(v) ? cos(v) : NaN) : own(x, :cos, a)
m_sin(@nospecialize(x), a...) = arith(x) ? (v = num(x); isfinite(v) ? sin(v) : NaN) : own(x, :sin, a)
m_round(@nospecialize(x), a...) = arith(x) ? floor(num(x) + 0.5) : own(x, :round, a)
m_ln(@nospecialize(x), a...) = arith(x) ? (v = num(x); v < 0 ? NaN : log(v)) : own(x, :ln, a)
m_exp(@nospecialize(x), a...) = arith(x) ? exp(num(x)) : own(x, :exp, a)
m_atan2(@nospecialize(x), a...) = arith(x) ? atan(num(x), num(a[1])) : rcall(x, :atan2, Any[a...])
m_pow(@nospecialize(x), a...) = arith(x) ? pw(num(x), num(a[1])) : rcall(x, :pow, Any[a...])

end # module Rt
